# Try: create a diamond shape centered somewhere
# Diamond from center of grid (row 7, col 4)

output = [[6]*8 for _ in range(15)]
center_r, center_c = 7, 3.5
row_range = 7

for r in range(center_r - row_range, center_r + row_range + 1):
    # Distance from center
    dist = abs(r - center_r)
    # Width at this row
    width = row_range - dist
    for r_idx in range(r, r + width):
        if 0 <= r_idx < 15:
            for c in range(center_c - dist + 1, center_c + dist + 1):
                if 0 <= c < 8:
                    output[r_idx][c] = 9

print("Diamond:")
for r, row in enumerate(output):
    print(f"{r}: {row}")

# Try: create a diamond shape
output = [[6]*8 for _ in range(15)]
center_r, center_c = 7, 3
row_range = 4

for r in range(center_r - row_range, center_r + row_range + 1):
    dist = abs(r - center_r)
    width = row_range - dist
    if width <= 0:
        continue
    for c in range(center_c - dist, center_c + dist + 1):
        if 0 <= c < 8:
            output[r][c] = 9

print("Diamond:")
for r, row in enumerate(output):
    print(f"{r}: {row}")
